/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  Easing,
  random,
} from '../remotionShim';
// Font loading at module level
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadRoboto = makeLoadFont('Roboto');
const loadMontserrat = makeLoadFont('Montserrat');

const { fontFamily: interFamily } = loadInter();
const { fontFamily: robotoFamily } = loadRoboto();
const { fontFamily: montserratFamily } = loadMontserrat();



export type RetroFlightProps = Record<string, any>;

const RetroFlight: React.FC<RetroFlightProps> = ({
  backgroundColor = "#050508",
  transparentBackground = false,
  durationInSeconds = 8,
  text = "MALLOY",
  textEntrySide = "left",
  fontFamily = "Inter",
  fontSize = 320,
  letterSpacing = 10,
  textColor = "#ffffff",
  bandColors = ["#ff3300", "#ccee00", "#3355ff"],
  glowIntensity = 100,
  chromaticAberration = 12,
  scanlineIntensity = 0.6,
  animationSpeed = 1,
  enableFlicker = true,
  flickerIntensity = 20,
  enableStatic = true,
  staticIntensity = 30,
}) => {
  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();

  // Handle transparent background
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Resolve font
  const font =
    fontFamily === "Inter"
      ? interFamily
      : fontFamily === "Roboto"
      ? robotoFamily
      : montserratFamily;

  // Time & Animation bounds
  const durationInFrames = durationInSeconds * fps;
  const adjFrame = frame * animationSpeed;

  // -- BANDS ANIMATION --
  const sweepEndFrame = fps * 1.5;
  
  const sweepProgress = interpolate(adjFrame, [0, sweepEndFrame], [0, 1], {
    easing: Easing.inOut(Easing.quad),
    extrapolateRight: "clamp",
  });
  
  // Removed the drift progress so bands stop shifting once they land
  const bandX = interpolate(sweepProgress, [0, 1], [-width * 3, -width * 2]);

  // -- TEXT ANIMATION --
  const textStartFrame = fps * 1.5; 
  const textMidFrame = textStartFrame + fps * 1.5;
  const textEndFrame = durationInFrames;

  const clampedTextFrame = Math.max(textStartFrame, Math.min(adjFrame, textEndFrame));

  // 1. Base X Position
  const startXPosition = textEntrySide === "left" ? -width * 1.2 : width * 1.2;
  const textSettleX = width * 0.15; // Initial landing slightly right of center

  // Removed secondary drift interpolation so the text fully settles in place
  const textBaseX = interpolate(
    clampedTextFrame,
    [textStartFrame, textMidFrame],
    [startXPosition, textSettleX],
    {
      easing: Easing.out(Easing.exp),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // 2. Letter Spread
  const baseCharWidth = fontSize * 0.75 + letterSpacing; 
  const textSpread = interpolate(
    clampedTextFrame,
    [textStartFrame, textMidFrame],
    [fontSize * 0.5, 0],
    {
      easing: Easing.out(Easing.quad),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  const chars = text.split("");
  const centerIdx = (chars.length - 1) / 2;

  // Calculate total dynamic width of the text block for the solid mask
  const maskWidth = Math.max(0, (chars.length - 1) * (baseCharWidth + textSpread)) + baseCharWidth + fontSize * 0.8;

  // Chromatic Aberration Shadow
  const caShadow = chromaticAberration > 0 ? `
    -${chromaticAberration}px 0 0 rgba(255, 0, 0, 0.8),
    ${chromaticAberration}px 0 0 rgba(0, 255, 255, 0.8)
  ` : "none";

  // Deterministic Flicker
  const flickerValue = enableFlicker && flickerIntensity > 0
    ? interpolate(random(`flicker-${frame}`), [0, 1], [1 - (flickerIntensity / 100), 1])
    : 1;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      
      {/* 
        Isolation Wrapper with Flicker Opacity applied.
        Creates a closed stacking context so the destination-out mask ONLY punches 
        holes through the bands layer, revealing the AbsoluteFill's background color.
      */}
      <div style={{ position: "absolute", inset: 0, isolation: "isolate", opacity: flickerValue }}>
        
        {/* 1. BACKGROUND COLOR BANDS */}
        <div
          style={{
            position: "absolute",
            top: "50%",
            left: 0,
            transform: `translateY(-50%) translateX(${bandX}px)`,
            width: width * 3,
            display: "flex",
            flexDirection: "column",
            gap: 0,
            transition: "none",
            zIndex: 0,
          }}
        >
          {bandColors.map((color, idx) => (
            <div
              key={`band-${idx}`}
              style={{
                height: height * 0.08,
                backgroundColor: color,
                boxShadow: glowIntensity > 0 ? `0 0 ${glowIntensity}px ${color}` : "none",
                width: "100%",
                transition: "none",
              }}
            />
          ))}
        </div>

        {/* 2. SOLID BLOCK MASK (Erases the bands behind and between the entire word) */}
        <div
          style={{
            position: "absolute",
            top: "50%",
            left: "50%",
            transform: `translate(-50%, -50%) translateX(${textBaseX}px)`,
            width: maskWidth,
            height: "100%",
            backgroundColor: "black",
            mixBlendMode: "destination-out" as any,
            transition: "none",
            zIndex: 1,
          }}
        />

        {/* 3. TEXT CONTAINER */}
        <div
          style={{
            position: "absolute",
            inset: 0,
            transition: "none",
            zIndex: 2,
          }}
        >
          {chars.map((char, i) => {
            const charOffset = (i - centerIdx) * (baseCharWidth + textSpread);
            const finalX = textBaseX + charOffset;

            return (
              <React.Fragment key={`char-${i}`}>
                {/* Massive Bloom Layer (Behind core text, over the erased background) */}
                {glowIntensity > 0 && (
                  <div
                    style={{
                      position: "absolute",
                      top: "50%",
                      left: "50%",
                      transform: `translate(-50%, -50%) translateX(${finalX}px)`,
                      fontFamily: font,
                      fontWeight: 900,
                      fontSize: fontSize,
                      color: textColor,
                      filter: `blur(${glowIntensity * 1.5}px)`,
                      opacity: 0.9,
                      lineHeight: 1,
                      transition: "none",
                      zIndex: 2,
                    }}
                  >
                    {char}
                  </div>
                )}

                {/* Core Text Layer */}
                <div
                  style={{
                    position: "absolute",
                    top: "50%",
                    left: "50%",
                    transform: `translate(-50%, -50%) translateX(${finalX}px)`,
                    fontFamily: font,
                    fontWeight: 900,
                    fontSize: fontSize,
                    color: textColor,
                    textShadow: caShadow,
                    lineHeight: 1,
                    transition: "none",
                    zIndex: 3,
                  }}
                >
                  {char}
                </div>
              </React.Fragment>
            );
          })}
        </div>
      </div>

      {/* 4. CRT / SCANLINE OVERLAY */}
      {scanlineIntensity > 0 && (
        <div
          style={{
            position: "absolute",
            inset: 0,
            pointerEvents: "none",
            zIndex: 10,
            backgroundImage: `
              linear-gradient(rgba(0, 0, 0, 0) 50%, rgba(0, 0, 0, ${0.4 * scanlineIntensity}) 50%),
              linear-gradient(90deg, rgba(255, 0, 0, ${0.05 * scanlineIntensity}), rgba(0, 255, 0, ${0.02 * scanlineIntensity}), rgba(0, 0, 255, ${0.05 * scanlineIntensity}))
            `,
            backgroundSize: "100% 6px, 9px 100%",
            mixBlendMode: "multiply",
            transition: "none",
          }}
        />
      )}

      {/* 5. TV STATIC OVERLAY */}
      {enableStatic && staticIntensity > 0 && (
        <div
          style={{
            position: "absolute",
            inset: 0,
            pointerEvents: "none",
            zIndex: 11,
            opacity: (staticIntensity / 100) * 0.4,
            mixBlendMode: "overlay",
            transition: "none",
          }}
        >
          <svg width="100%" height="100%">
            <filter id="tvNoise">
              <feTurbulence
                type="fractalNoise"
                baseFrequency="0.8"
                numOctaves="3"
                stitchTiles="stitch"
                seed={frame % 100} // Deterministic animating seed based on frame
              />
              <feColorMatrix type="saturate" values="0" />
            </filter>
            <rect width="100%" height="100%" filter="url(#tvNoise)" />
          </svg>
        </div>
      )}
    </AbsoluteFill>
  );
};

export default RetroFlight;